package com.sift.app.data.repository

import com.sift.app.data.network.ApiCaller
import com.sift.app.data.remote.SiftApi
import com.sift.app.data.remote.dto.ReplyRequestDto
import com.sift.app.domain.error.AppError
import com.sift.app.domain.model.ReplyDraft
import com.sift.app.domain.model.ReplyTone
import com.sift.app.domain.repository.ReplyRepository

/** Reply drafts generated by the backend's reasoning model. */
class ReplyRepositoryImpl(
    private val api: SiftApi,
    private val caller: ApiCaller
) : ReplyRepository {
    override suspend fun draftReply(reviewRemoteId: Long, tone: ReplyTone): ReplyDraft {
        val dto = caller.call { api.draftReply(reviewRemoteId, ReplyRequestDto(tone.key)) }
        val text = dto.text?.takeIf { it.isNotBlank() } ?: throw AppError.Unexpected()
        return ReplyDraft(text, tone)
    }
}
